const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const cats=[['Vegetables & fruits','🥬','#eef3e7'],['Dairy & breakfast','🥛','#eef0fa'],['Atta, rice & dal','🌾','#f8f0df'],['Snacks & munchies','🍿','#fff0e3'],['Beverages','🧃','#edf2e2'],['Home & care','🧴','#f0eefa'],['All','🛒','#f8eee5']];
function read(k,d){try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}}
function saveLocal(k,value){try{localStorage.setItem(k,JSON.stringify(value))}catch{}}
let products=[],cart=WCCart.normalize(read('wk-cart',{})),orders=[],category='All',filter='all',catalogReady=false;
const money=v=>'₹'+Number(v).toLocaleString('en-IN');
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function persist(){saveLocal('wk-cart',cart)}
function notify(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),2800)}
function art(p){return p.pack?`<div class="pack" style="background:${/^#[0-9a-f]{6}$/i.test(p.color||'')?p.color:'#eef3e7'};color:${p.white?'white':'#345131'}"><small>${escape(p.sub)}</small>${escape(p.pack)}<span class="packicon">${escape(p.emoji)}</span><small>${escape(p.unit)}</small></div>`:`<span class="emoji">${escape(p.emoji)}</span>`}
function qty(p){return cart[p.id]?`<div class="qty"><button data-change="${p.id}" data-n="-1" aria-label="Remove one ${escape(p.name)}">−</button><b>${cart[p.id]}</b><button data-change="${p.id}" data-n="1" aria-label="Add one ${escape(p.name)}">+</button></div>`:`<button class="add" data-change="${p.id}" data-n="1" ${p.stock<1?'disabled':''}>${p.stock<1?'SOLD OUT':'ADD +'}</button>`}
function render(){let list=products.filter(p=>(category==='All'||cats[p.cat][0]===category)&&p.name.toLowerCase().includes($('#search').value.toLowerCase())&&(filter!=='deals'||p.mrp>p.price)&&(filter!=='stock'||p.stock>0));if($('#sort').value==='low')list.sort((a,b)=>a.price-b.price);if($('#sort').value==='high')list.sort((a,b)=>b.price-a.price);$('#producttitle').textContent=category==='All'?'Fresh picks for your basket':category;$('#resultcount').textContent=list.length+' products';$('#products').innerHTML=list.length?list.map(p=>`<article class="product-card"><div class="product-image">${p.mrp>p.price?`<span class="discount">${Math.round((1-p.price/p.mrp)*100)}% OFF</span>`:''}${art(p)}</div><span class="time">◷ 25–35 MINS</span><h3>${escape(p.name)}</h3><div class="unit">${escape(p.unit)}</div><div class="product-bottom"><div class="price">${money(p.price)}${p.mrp>p.price?`<del>${money(p.mrp)}</del>`:''}</div>${qty(p)}</div></article>`).join(''):(catalogReady?'<div class="empty">No products found. Try another search or category.</div>':'<div class="empty">Loading current stock…</div>');let count=Object.values(cart).reduce((a,b)=>a+b,0);$('#count').textContent=count;$('#cartlabel').textContent=count?money(total()):'My cart';$$('[data-cat]').forEach(b=>b.classList.toggle('active',b.dataset.cat===category));}
function total(){return Math.round(products.reduce((s,p)=>s+Math.round(p.price*100)*(cart[p.id]||0),0))/100}
function change(id,n){let p=products.find(p=>p.id===id);if(!p||!Number.isInteger(n))return;if((cart[id]||0)+n>Math.min(p.stock,100))return notify('Only '+p.stock+' available in stock');cart[id]=Math.max(0,(cart[id]||0)+n);if(!cart[id])delete cart[id];persist();render();if(!$('#drawer').hidden)drawCart()}
$('#categories').innerHTML=cats.map(([name,emoji,color])=>`<button class="category-card" data-cat="${name}"><div class="category-picture" style="background:${color}"><span>${emoji}</span></div><b>${name==='All'?'Shop all essentials':name}</b></button>`).join('');
document.addEventListener('click',e=>{let c=e.target.closest('[data-cat]');if(c){category=c.dataset.cat;render();$('#products-section').scrollIntoView({behavior:'smooth',block:'start'})}let b=e.target.closest('[data-change]');if(b)change(Number(b.dataset.change),Number(b.dataset.n));let f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;$$('[data-filter]').forEach(x=>x.classList.toggle('selected',x===f));render()}});
$('#search').addEventListener('input',()=>{render()});$('#sort').onchange=render;$('#shopnow').onclick=()=>$('#products-section').scrollIntoView({behavior:'smooth'});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();$('#search').focus()}if(e.key==='Escape')closeCart()});
function closeCart(){$('#drawer').hidden=true;$('#overlay').hidden=true;document.body.style.overflow=''}
$('#cartbtn').onclick=()=>{$('#drawer').hidden=false;$('#overlay').hidden=false;document.body.style.overflow='hidden';drawCart();$('#closecart').focus()};$('#overlay').onclick=closeCart;
function showModal(html){$('#modal').innerHTML=`<button class="close" style="float:right" data-close-dialog aria-label="Close dialog">×</button>${html}`;$('#modal').showModal()}

function checkout(){notify('Connecting to checkout…')}
function drawCart(){notify('Connecting to your basket…')}
document.addEventListener('click',event=>{if(event.target.closest('[data-close-dialog]'))document.querySelector('dialog')?.close()});
render();
